ga5n(){return"\u0634\u0648\u06ce\u0646\u06a9\u06d5\u0648\u062a\u0646\u06cc \u0633\u06d5\u0631\u062f\u0627\u0646\u06cc \u0645\u06d5\u0646\u062f\u0648\u0628"},
ga5o(){return'\u0686\u06d5\u0646\u062f \u0695\u06c6\u0698 \u062f\u06d5\u0628\u06ce\u062a \u062a\u06ce\u067e\u06d5\u0695\u06ce\u062a \u0644\u06d5 \u062f\u0648\u0627\u06cc\u06cc\u0646 \u0633\u06d5\u0631\u062f\u0627\u0646\u06cc \u0645\u06d5\u0646\u062f\u0648\u0628 \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9 \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0648\u06d5\u06a9 "\u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc \u0628\u06d5 \u0633\u06d5\u0631\u062f\u0627\u0646 \u0647\u06d5\u06cc\u06d5" \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u0631\u06ce\u062a \u0644\u06d5 \u062a\u0627\u0628\u06cc \u0633\u06d5\u0631\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646.'},
ga5m(){return"\u0645\u0627\u0648\u06d5\u06cc \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646\u06cc \u0646\u06ce\u0648\u0627\u0646 \u0633\u06d5\u0631\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 (\u0695\u06c6\u0698)"},
ga3G(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646"},
ga3H(){return"\u067e\u06ce\u0634 \u0647\u06d5\u0645\u0648\u0648 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5\u06a9\u06cc \u06a9\u06d5\u06cc\u0633 \u0644\u06d5 \u0628\u06d5\u0631\u0646\u0627\u0645\u06d5 \u0648 \u0686\u0627\u067e\u062f\u0627 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u062a\u06d5\u0646\u0647\u0627 \u0698\u0645\u0627\u0631\u06d5 (64)\u060c \u06cc\u0627\u0646 \u06a9\u06c6\u062f\u06cc \u062e\u06c6\u062a \u0628\u0646\u0648\u0648\u0633\u06d5 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 ALM- \u0628\u06c6 ALM-64)."},
