gamf(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06cc\u0627\u0633\u0627\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
gam6(){return"\u06cc\u0627\u0633\u0627\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
