game(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
gWs(){return"\u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646"},
gama(){return"\u0646\u0631\u062e (\u0628\u0695 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9\u060c \u06cc\u0627\u0646 %)"},
